export type ParsedRepayInstruction<
  TProgram extends string = typeof SHORTWIN_SIMPLE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    actor: TAccountMetas[0];
    config: TAccountMetas[1];
    policy: TAccountMetas[2];
    market: TAccountMetas[3];
    pool: TAccountMetas[4];
    loan: TAccountMetas[5];
    exposure: TAccountMetas[6];
    borrower: TAccountMetas[7];
    mint: TAccountMetas[8];
    tokenVault: TAccountMetas[9];
    tokenProgram: TAccountMetas[10];
    source: TAccountMetas[11];
    eventAuthority: TAccountMetas[12];
    program: TAccountMetas[13];
  };
  data: RepayInstructionData;
};

export function parseRepayInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRepayInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 14) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 14,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      actor: getNextAccount(),
      config: getNextAccount(),
      policy: getNextAccount(),
      market: getNextAccount(),
      pool: getNextAccount(),
      loan: getNextAccount(),
      exposure: getNextAccount(),
      borrower: getNextAccount(),
      mint: getNextAccount(),
      tokenVault: getNextAccount(),
      tokenProgram: getNextAccount(),
      source: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getRepayInstructionDataDecoder().decode(instruction.data),
  };
}
